284				byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
285				StringBuilder sb = new StringBuilder(digest.length * 2);
286				for (byte b : digest) {
287					sb.append(String.format("%02x", b));
288				}
289				return sb.toString();
290			}
291			catch (Exception e) {
